import React, { useCallback, useMemo, type ReactNode } from 'react';
import { useContentfulEntries } from 'app/hooks/useContentful';
import { UiCopyContext } from 'app/hooks/useUiCopy';
import type { UiCopyEntry } from 'app/types/contentful';

type UiCopyProviderProps = {
  children: ReactNode;
};

/**
 * Bulk-fetches every `uiCopy` entry in one Delivery API call (`content_type=uiCopy`) and
 * provides the resulting key→value lookup to every descendant via useUiCopy() — mounted once
 * in _app-config, so creating N entries in Contentful costs one call for the whole app, not N
 * calls from N components each independently fetching the same content.
 *
 * @param props.children the app tree to provide uiCopy lookups to
 */
export const UiCopyProvider = ({ children }: UiCopyProviderProps) => {
  const { data, isLoading } = useContentfulEntries<UiCopyEntry>('uiCopy');

  const copyMap = useMemo(() => {
    const map = new Map<string, string>();
    (data ?? []).forEach((entry) => {
      map.set(entry.fields.key, entry.fields.value);
    });
    return map;
  }, [data]);

  // Fallback-on-failure by design, not just a loading placeholder: unlike structural content
  // (e.g. FooterContainer's footerConfig, which renders nothing rather than substitute
  // placeholder content), losing a button label or a status message to a Contentful outage
  // should never blank a control.
  const t = useCallback((key: string, fallback: string): string => copyMap.get(key) ?? fallback, [copyMap]);

  const value = useMemo(() => ({ t, isLoading }), [t, isLoading]);

  return <UiCopyContext.Provider value={value}>{children}</UiCopyContext.Provider>;
};

