const ContentfulPreview = loadable(() => import('./pages/contentfulPreview'), {fallback});

const routes = [
  {
    path: '/',
    component: Home,
    exact: true,
  },
  {
    path: '/my-new-route',
    component: MyNewRoute,
  },
  ..._routes,
  // Contentful Live Preview — must be before /:slug so it takes priority.
  {
    path: '/preview',
    component: ContentfulPreview,
    exact: true,
