 39	import type { HomepageEntry, AnyContentfulEntry } from '../../types/contentful';
 40	import PageContainer from '../../components/pageContainer';
 41	
 42	// --- Shared layout ---
 43	
 44	type HomepageContentProps = {
 45	  fields: HomepageEntry['fields'];
 46	  entryId: string;
 47	};
 48	
 49	const HomepageContent = ({ fields, entryId }: HomepageContentProps) => {
 50	  const intl = useIntl();
 51	
 52	  const { data: productSearchResult, isLoading: productsLoading } = useProductSearch({
 53	    parameters: {
 54	      refine: [`cgid=${HOME_SHOP_PRODUCTS_CATEGORY_ID as string}`, 'htype=master'] as unknown as string, // SDK types refine as string but runtime accepts string[]
 55	      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
 56	      perPricebook: true,
 57	      allVariationProperties: true,
 58	      limit: HOME_SHOP_PRODUCTS_LIMIT,
 59	    },
 60	  });
 61	
 62	  return (
 63	    <>
 64	      {fields.heroBanner && (
 65	        <PageContainer boxed="desktop">
 66	          <HeroBanner heroBanner={fields.heroBanner} entryId={entryId} />
 67	        </PageContainer>
 68	      )}
 69	      {fields.duplexSection && <DuplexSection duplexSection={fields.duplexSection} entryId={entryId} />}
 70	      {fields.videoEmbed && <VideoEmbed videoEmbed={fields.videoEmbed} entryId={entryId} />}
 71	      {fields.productHero && (
 72	        <>
 73	          <Box maxWidth="container.xl" marginX="auto" paddingX={8} paddingTop={12}>
 74	            <Text as="h3" fontSize="2xl" fontWeight="bold" marginBottom={2}>
 75	              Featured Product
 76	            </Text>
 77	          </Box>
 78	          <ProductHero productHero={fields.productHero} entryId={entryId} />
 79	        </>
 80	      )}
 81	      {productSearchResult && (
 82	        // From PWA template - Example on how to show products
 83	        <Section
 84	          padding={4}
 85	          paddingTop={16}
 86	          title={intl.formatMessage({
 87	            defaultMessage: 'Shop Products',
