 92	              defaultMessage: 'This section contains content from the catalog. {docLink} on how to replace it.',
 93	              id: 'home.description.shop_products',
 94	              description:
 95	                '{docLink} is a html button that links the user to https://sfdc.co/business-manager-manage-catalogs',
 96	            },
 97	            {
 98	              docLink: (
 99	                <Link
100	                  target="_blank"
101	                  href={'https://sfdc.co/business-manager-manage-catalogs'}
102	                  textDecoration={'none'}
103	                  position={'relative'}
104	                  _after={{
105	                    position: 'absolute',
106	                    content: `""`,
107	                    height: '2px',
108	                    bottom: '-2px',
109	                    margin: '0 auto',
110	                    left: 0,
111	                    right: 0,
112	                    background: 'gray.700',
113	                  }}
114	                  _hover={{ textDecoration: 'none' }}
115	                >
116	                  {intl.formatMessage({
117	                    defaultMessage: 'Read docs',
118	                    id: 'home.link.read_docs',
119	                  })}
120	                </Link>
121	              ),
122	            },
123	          )}
124	        >
125	          <Stack pt={8} spacing={16}>
126	            <ProductScroller products={productSearchResult?.hits} isLoading={productsLoading} />
127	          </Stack>
128	        </Section>
129	      )}
130	    </>
131	  );
132	};
133	
134	// --- Normal (published) home ---
135	
136	const HomeNormal = () => {
137	  const einstein = useEinstein();
138	  const { pathname } = useLocation();
139	
140	  const { res } = useServerContext();
141	  if (res) {
142	    res.set(
143	      'Cache-Control',
144	      `s-maxage=${MAX_CACHE_AGE as number}, stale-while-revalidate=${STALE_WHILE_REVALIDATE as number}`,
145	    );
146	  }
147	
148	  const { data: contentfulData, isLoading: contentfulLoading } = useContentfulEntries<HomepageEntry>('homepage');
149	  const homepageContent = useContentfulLiveUpdates(contentfulData?.[0] ?? null);
150	
151	  useEffect(() => {
152	    einstein.sendViewPage(pathname);
153	  }, []);
154	
155	  if (contentfulLoading) {
156	    return (
157	      <Box display="flex" justifyContent="center" py={16}>
158	        <Spinner size="xl" />
159	      </Box>
160	    );
161	  }
162	
163	  if (!homepageContent) return null;
164	
165	  return <HomepageContent fields={homepageContent.fields} entryId={homepageContent.sys.id} />;
166	};
167	
168	// --- Preview (draft) home ---
169	
170	type HomePreviewContentProps = {
171	  entryId: string;
172	};
173	
174	const HomePreviewContent = ({ entryId }: HomePreviewContentProps) => {
175	  const { data, isLoading, error } = useContentfulEntry<AnyContentfulEntry>(entryId, true);
176	  const liveData = useContentfulLiveUpdates(data);
177	
178	  if (isLoading) {
179	    return (
180	      <Box display="flex" justifyContent="center" py={16}>
181	        <Spinner size="xl" />
182	      </Box>
183	    );
184	  }
185	
186	  if (error) {
187	    return (
188	      <Box p={8}>
189	        <Text color="red.500">Error loading preview: {error.message}</Text>
190	      </Box>
191	    );
192	  }
193	
194	  if (!liveData) return null;
195	
196	  const contentTypeId = liveData.sys?.contentType?.sys?.id;
197	
198	  if (contentTypeId !== 'homepage') {
199	    return (
200	      <Box p={8}>
201	        <Text>Preview for content type &ldquo;{contentTypeId}&rdquo; is not yet configured.</Text>
202	      </Box>
203	    );
204	  }
205	
206	  return <HomepageContent fields={liveData.fields as HomepageEntry['fields']} entryId={liveData.sys.id} />;
207	};
208	
209	// --- Page ---
210	
211	const Home = () => {
212	  const { search } = useLocation();
213	  const entryId = new URLSearchParams(search).get('entry');
214	
215	  return (
216	    <Box data-testid="home-page">
217	      <Seo
218	        title="Home Page"
219	        description="Commerce Cloud Retail React App"
220	        keywords="Commerce Cloud, Retail React App, React Storefront"
221	      />
222	      {entryId ? <HomePreviewContent entryId={entryId} /> : <HomeNormal />}
223	    </Box>
224	  );
225	};
226	
227	Home.getTemplateName = () => 'home';
228	
229	export default Home;

