  1	import React, { useEffect, useState } from 'react';
  2	import type { ContentfulClientApi } from 'contentful';
  3	import Seo from '@salesforce/retail-react-app/app/components/seo';
  4	import { useLocation } from 'react-router-dom';
  5	import { Box, Spinner, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
  6	import { ExperienceRoot, useFetchBySlug } from '@contentful/experiences-sdk-react';
  7	import { StudioCanvasMode } from '@contentful/experiences-core/constants';
  8	import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';
  9	import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
 10	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
 11	import { CONTENTFUL_FALLBACK_LOCALE, CONTENTFUL_LIVE_PREVIEW_ORIGIN } from '../../config/contentful';
 12	import { useContentfulClient } from '../../hooks/useContentfulClient';
 13	
 14	// Side-effect import — registers experience components with the Contentful Experiences SDK (cached, so this is fine)
 15	import '../../components/contentful/experiences/definitions';
 16	
 17	const EXPERIENCE_TYPE_ID = 'collectionPageExp';
 18	
 19	type ExperienceFetchProps = {
 20	  client: ContentfulClientApi<any>;
 21	  slug: string;
 22	  locale: string;
 23	  isPreview: boolean;
 24	};
 25	
 26	/** Inner component so useFetchBySlug is always called unconditionally at the top level. */
 27	const ExperienceFetch = ({ client, slug, locale, isPreview }: ExperienceFetchProps) => {
 28	  const { experience, isLoading, error, mode } = useFetchBySlug({
 29	    client: client as any,
 30	    slug,
 31	    experienceTypeId: EXPERIENCE_TYPE_ID,
 32	    localeCode: locale,
 33	  });
 34	
 35	  // Inside Contentful Studio's Experience Builder canvas iframe, useFetchBySlug deliberately never
 36	  // fetches or returns an `experience` — the real data is supplied to ExperienceRoot separately via
 37	  // postMessage from Studio (@contentful/experiences-sdk-react's useFetchByBase, "supervised mode").
 38	  // ExperienceRoot already branches on `mode` before ever looking at the `experience` prop, so it must
 39	  // still be mounted here even when `experience` is undefined — bailing out to "Page not found" in this
 40	  // case (as a plain `!experience` check would) prevents the canvas from ever rendering at all.
 41	  const isSupervisedMode = mode === StudioCanvasMode.EDITOR || mode === StudioCanvasMode.READ_ONLY;
 42	
 43	  if (isLoading) {
 44	    return (
 45	      <Box p={8} display="flex" justifyContent="center">
 46	        <Spinner size="xl" />
 47	      </Box>
 48	    );
 49	  }
 50	
 51	  if (!isSupervisedMode && (error || !experience)) {
 52	    // noindex so a missing/unresolved slug isn't indexed as valid content. NOTE: a true HTTP 404
 53	    // isn't set here — useFetchBySlug resolves client-side (post-hydration), so `res` is unavailable
 54	    // and SSR has already sent 200. A real 404 needs SSR prefetch (getProps) — tracked separately.
 55	    return (
 56	      <>
 57	        <Seo noIndex />
 58	        <Box p={8}>
 59	          <Text color="red.500">Page not found.</Text>
 60	        </Box>
 61	      </>
 62	    );
 63	  }
 64	
 65	  const root = <ExperienceRoot experience={experience} locale={locale} />;
 66	
 67	  if (isPreview) {
 68	    return (
 69	      <>
 70	        {/* noindex — preview mode serves draft content, must not be indexed */}
 71	        <Seo noIndex />
 72	        <ContentfulLivePreviewProvider
 73	          locale={locale}
 74	          enableInspectorMode={true}
 75	          enableLiveUpdates={true}
 76	          targetOrigin={CONTENTFUL_LIVE_PREVIEW_ORIGIN}
 77	        >
 78	          {root}
 79	        </ContentfulLivePreviewProvider>
 80	      </>
 81	    );
 82	  }
 83	
 84	  return root;
 85	};
 86	
 87	type ExperiencePageProps = {
 88	  slug: string;
 89	  isPreview?: boolean;
 90	  isEditorCanvas?: boolean;
 91	};
 92	
 93	const ExperiencePage = ({ slug, isPreview = false, isEditorCanvas = false }: ExperiencePageProps) => {
 94	  const { locale: siteLocale } = useMultiSite() as { locale?: { id: string } };
 95	  const locale = siteLocale?.id || CONTENTFUL_FALLBACK_LOCALE;
 96	  const { res } = useServerContext();
 97	  // Preview requests use the CPA host+token only when a token is configured; otherwise the page
 98	  // renders in normal delivery mode. A preview request WITHOUT a token is handled explicitly
 99	  // below (404 + noindex) — it never silently falls back to delivery.
100	  const {
101	    client,
102	    previewUnavailable,
103	    isPreview: effectivePreview,
104	  } = useContentfulClient({
105	    preview: isPreview,
106	  });
107	
108	  // @contentful/experiences-sdk-react's useFetchBySlug (called inside ExperienceFetch) branches its
109	  // initial canvas-mode state on `typeof window !== 'undefined'`, which differs between the SSR pass
110	  // and the client's first hydration pass when this page loads inside Contentful Studio's Experience
111	  // Builder canvas iframe — a structural hydration mismatch (React errors #418/#423) that discards the
